css:
  :root {
    --bg: #F3F4F6;
    --surface: #FFFFFF;
    --ink: #15171B;
    --ink-2: #3E4450;
    --muted: #667085;
    --faint: #8A909B;
    --line: #E4E7EC;
    --line-2: #D0D5DD;
    --focus: #2F5BFF;
    --radius-card: 8px;
    --radius-ctl: 5px;
    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  }

  *, *::before, *::after { box-sizing: border-box; }

  html { -webkit-text-size-adjust: 100%; }

  body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: var(--sans);
    font-size: 14px;
    line-height: 1.45;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  ::selection { background: #DCE4FF; }

  button, input, select { font: inherit; color: inherit; }
  button { cursor: pointer; }
  svg { display: block; }

  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .wrap {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto;
    padding-left: 32px;
    padding-right: 32px;
  }

.appbar {
    background: #131518;
    color: #F5F6F7;
  }

  .appbar-in {
    height: 52px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
  }

  .brand {
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 0;
  }

  .brand-mark {
    flex: none;
    color: rgba(255, 255, 255, 0.8);
  }

  .brand-name {
    font-size: 12.5px;
    line-height: 18px;
    font-weight: 600;
    letter-spacing: 0.01em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .avatar {
    flex: none;
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #343A43;
    border-radius: 5px;
    background: #22262C;
    color: #CDD2D9;
    font-size: 10.5px;
    line-height: 1;
    font-weight: 600;
    letter-spacing: 0.03em;
  }

  .page {
    padding-top: 34px;
    padding-bottom: 72px;
  }

  .page-title {
    margin: 0 0 20px;
    font-size: 26px;
    line-height: 32px;
    font-weight: 600;
    letter-spacing: -0.022em;
    color: #121418;
  }

  .panel {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: var(--radius-card);
    box-shadow: 0 1px 2px rgba(16, 24, 40, 0.03);
    overflow: hidden;
  }
.toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px 18px;
    border-bottom: 1px solid var(--line);
  }

  .search {
    position: relative;
    flex: 0 1 360px;
    min-width: 200px;
  }

  .search-icon {
    position: absolute;
    left: 11px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--faint);
    pointer-events: none;
  }

  .search input {
    width: 100%;
    height: 36px;
    padding: 0 12px 0 33px;
    border: 1px solid var(--line-2);
    border-radius: var(--radius-ctl);
    background: var(--surface);
    font-size: 14px;
    color: var(--ink);
    outline: none;
    appearance: none;
    -webkit-appearance: none;
    transition: border-color 0.12s ease, box-shadow 0.12s ease;
  }

  .search input::-webkit-search-cancel-button {
    -webkit-appearance: none;
    appearance: none;
  }

  .search input::placeholder { color: #6E7683; opacity: 1; }

  .search input:hover { border-color: #B8BFCA; }

  .search input:focus {
    border-color: var(--focus);
    box-shadow: 0 0 0 3px rgba(47, 91, 255, 0.14);
  }

  .filter {
    position: relative;
    flex: 0 0 156px;
  }

  .filter select {
    width: 100%;
    height: 36px;
    padding: 0 30px 0 11px;
    border: 1px solid var(--line-2);
    border-radius: var(--radius-ctl);
    background: var(--surface);
    font-size: 14px;
    color: var(--ink-2);
    outline: none;
    appearance: none;
    -webkit-appearance: none;
    cursor: pointer;
    transition: border-color 0.12s ease, box-shadow 0.12s ease;
  }

  .filter select:hover { border-color: #B8BFCA; }

  .filter select:focus {
    border-color: var(--focus);
    box-shadow: 0 0 0 3px rgba(47, 91, 255, 0.14);
  }

  .filter-chevron {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--muted);
    pointer-events: none;
  }

  .toolbar-spacer { flex: 1 1 auto; }

  .btn-export {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    height: 36px;
    padding: 0 13px;
    border: 1px solid #15171B;
    border-radius: var(--radius-ctl);
    background: #15171B;
    color: #FFFFFF;
    font-size: 13px;
    line-height: 1;
    font-weight: 600;
    letter-spacing: 0.005em;
    white-space: nowrap;
    transition: background-color 0.12s ease, border-color 0.12s ease;
  }

  .btn-export:hover {
    background: #262A31;
    border-color: #262A31;
  }

  .btn-export:focus-visible,
  .btn-quiet:focus-visible,
  .page-btn:focus-visible {
    outline: 2px solid var(--focus);
    outline-offset: 2px;
  }
.orders {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .orders col.col-order { width: 15%; }
  .orders col.col-customer { width: 31%; }
  .orders col.col-status { width: 17%; }
  .orders col.col-amount { width: 19%; }
  .orders col.col-created { width: 18%; }

  .orders thead th {
    padding: 9px 18px;
    background: #FAFAFB;
    border-bottom: 1px solid var(--line);
    font-size: 12px;
    line-height: 16px;
    font-weight: 600;
    letter-spacing: 0.015em;
    color: #5F6773;
    text-align: left;
    white-space: nowrap;
  }

  .orders thead th.num { text-align: right; }

  .orders tbody td {
    padding: 13px 18px;
    border-bottom: 1px solid var(--line);
    font-size: 14px;
    line-height: 20px;
    vertical-align: middle;
    transition: background-color 0.1s ease;
  }

  .orders tbody tr:last-child td { border-bottom: 0; }

  .cell-order {
    font-family: var(--mono);
    font-size: 12px;
    letter-spacing: -0.01em;
    color: #69717E;
    white-space: nowrap;
  }

  .cell-customer {
    font-weight: 500;
    letter-spacing: -0.005em;
    color: #191C21;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .cell-status { white-space: nowrap; }

  .cell-amount {
    text-align: right;
    font-weight: 500;
    font-variant-numeric: tabular-nums;
    color: #191C21;
    white-space: nowrap;
  }

  .cell-created {
    font-size: 14px;
    font-variant-numeric: tabular-nums;
    color: #4B5563;
    white-space: nowrap;
  }

  @media (hover: hover) {
    .orders tbody tr:hover td { background: #FAFBFC; }
  }

  .chip {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    min-height: 22px;
    padding: 2px 7px;
    border: 1px solid transparent;
    border-radius: 4px;
    font-size: 12px;
    line-height: 16px;
    font-weight: 600;
    letter-spacing: 0.005em;
    white-space: nowrap;
  }

  .chip .dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    flex: none;
  }

  .chip.paid {
    color: #05603A;
    background: #E9F6EE;
    border-color: #C3E7D2;
  }

  .chip.paid .dot { background: #0E8A4F; }

  .chip.pending {
    color: #8A4B00;
    background: #FFF4D9;
    border-color: #F2D9A4;
  }

  .chip.pending .dot { background: #C47A0A; }

  .chip.refunded {
    color: #B42318;
    background: #FDEDEC;
    border-color: #F5CECA;
  }

  .chip.refunded .dot { background: #D92D20; }
.pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 11px 18px;
    border-top: 1px solid var(--line);
    background: #FBFBFC;
  }

  .page-summary {
    margin: 0;
    font-size: 13px;
    line-height: 18px;
    color: var(--muted);
    font-variant-numeric: tabular-nums;
  }

  .page-mobile {
    display: none;
    font-size: 13px;
    line-height: 18px;
    color: var(--muted);
    font-variant-numeric: tabular-nums;
  }

  .page-controls {
    display: flex;
    align-items: center;
    gap: 2px;
  }

  .page-btn {
    min-width: 28px;
    height: 28px;
    padding: 0 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid transparent;
    border-radius: 4px;
    background: transparent;
    color: #4B5563;
    font-size: 13px;
    line-height: 1;
    font-weight: 500;
    font-variant-numeric: tabular-nums;
    transition: background-color 0.12s ease, color 0.12s ease;
  }

  .page-btn:hover:not(:disabled):not([aria-current="page"]) {
    background: #F0F2F4;
    color: var(--ink);
  }

  .page-btn[aria-current="page"] {
    background: #15171B;
    border-color: #15171B;
    color: #FFFFFF;
    font-weight: 600;
  }

  .page-btn:disabled {
    color: #B7BDC6;
    cursor: not-allowed;
  }

  .page-btn.arrow {
    width: 28px;
    padding: 0;
  }

  .page-gap {
    min-width: 20px;
    text-align: center;
    font-size: 12px;
    color: #98A0AC;
  }

  .state { margin-top: 32px; }

  .state-head {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
  }

  .state-head h2 {
    margin: 0;
    font-size: 12.5px;
    line-height: 18px;
    font-weight: 600;
    letter-spacing: 0.005em;
    color: #4B5563;
    white-space: nowrap;
  }

  .state-rule {
    flex: 1 1 auto;
    height: 1px;
    background: var(--line);
  }

  .empty {
    padding: 32px 24px 34px;
    border: 1px dashed #D3D8E0;
    border-radius: var(--radius-card);
    background: #FBFBFC;
    text-align: center;
  }

  .empty-icon {
    margin: 0 auto 11px;
    color: #98A0AB;
  }

  .empty h3 {
    margin: 0 0 4px;
    font-size: 14px;
    line-height: 20px;
    font-weight: 600;
    letter-spacing: -0.005em;
    color: #1B1E24;
  }

  .empty p {
    max-width: 360px;
    margin: 0 auto 15px;
    font-size: 14px;
    line-height: 20px;
    color: var(--muted);
  }

  .btn-quiet {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 32px;
    padding: 0 12px;
    border: 1px solid var(--line-2);
    border-radius: var(--radius-ctl);
    background: var(--surface);
    color: var(--ink-2);
    font-size: 13px;
    line-height: 1;
    font-weight: 600;
    transition: background-color 0.12s ease, border-color 0.12s ease;
  }

  .btn-quiet:hover {
    background: #F8F9FA;
    border-color: #B8BFCA;
  }

  @media (min-width: 765px) and (max-width: 900px) {
    .search { flex-basis: 280px; }
    .filter { flex-basis: 148px; }
  }

  @media (max-width: 764px) {
    .wrap {
      padding-left: 16px;
      padding-right: 16px;
    }

    .appbar-in { height: 48px; }

    .brand-name { font-size: 12px; }

    .avatar {
      width: 24px;
      height: 24px;
      font-size: 10px;
      border-radius: 4px;
    }

    .page {
      padding-top: 22px;
      padding-bottom: 48px;
    }

    .page-title {
      margin-bottom: 16px;
      font-size: 22px;
      line-height: 28px;
    }

    .panel { border-radius: 7px; }

    .toolbar {
      flex-wrap: wrap;
      gap: 8px;
      padding: 12px;
    }

    .search {
      flex: 1 1 100%;
      min-width: 0;
    }

    .search input {
      height: 40px;
      font-size: 16px;
    }

    .filter {
      flex: 1 1 auto;
      min-width: 0;
    }

    .filter select {
      height: 40px;
      font-size: 16px;
    }

    .btn-export {
      flex: 0 0 auto;
      height: 40px;
      padding: 0 14px;
      font-size: 13px;
    }

    .toolbar-spacer { display: none; }

    .orders,
    .orders tbody,
    .orders tr {
      display: block;
      width: 100%;
    }

    .orders td { display: block; }

    .orders thead {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .orders tbody tr {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr) auto;
      grid-template-areas:
        "order order status"
        "customer customer customer"
        "created created amount";
      align-items: center;
      column-gap: 12px;
      row-gap: 3px;
      padding: 12px 14px;
      border-bottom: 1px solid var(--line);
    }

    .orders tbody tr:last-child { border-bottom: 0; }

    .orders tbody td {
      height: auto;
      padding: 0;
      border: 0;
      background: transparent;
    }

    .cell-order {
      grid-area: order;
      font-size: 12px;
      line-height: 16px;
    }

    .cell-customer {
      grid-area: customer;
      font-size: 14px;
      line-height: 20px;
      white-space: normal;
      overflow: visible;
    }

    .cell-status {
      grid-area: status;
      justify-self: end;
      line-height: 1;
    }

    .cell-created {
      grid-area: created;
      font-size: 13px;
      line-height: 17px;
    }

    .cell-amount {
      grid-area: amount;
      justify-self: end;
      font-size: 14px;
      line-height: 17px;
    }

    .chip {
      font-size: 12px;
      min-height: 22px;
      padding: 2px 6px;
    }

    .pagination {
      padding: 10px 12px;
    }

    .page-summary { display: none; }

    .page-mobile { display: inline; }

    .page-btn:not(.arrow) { display: none; }

    .page-gap { display: none; }

    .page-controls { gap: 4px; }

    .page-btn {
      min-width: 32px;
      height: 32px;
    }

    .page-btn.arrow { width: 32px; }

    .state { margin-top: 26px; }

    .state-head { margin-bottom: 10px; }

    .empty {
      padding: 28px 18px 30px;
    }

    .empty p {
      max-width: 285px;
      margin-bottom: 14px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { transition-duration: 0.001ms !important; }
  }
